package org.zhbot.moonlight_antelope_hunting;

import net.runelite.api.Client;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

import javax.inject.Inject;
import java.awt.*;

public class MoonlightAntelopeHuntingInventoryOverlay extends WidgetItemOverlay {
    private final Client client;
    private final MoonlightAntelopeHuntingPlugin plugin;
    private final MoonlightAntelopeHuntingConfig config;

    @Inject
    private MoonlightAntelopeHuntingInventoryOverlay(Client client, MoonlightAntelopeHuntingPlugin plugin, MoonlightAntelopeHuntingConfig config)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;

        showOnInventory();
        setPriority(2f);
    }

    @Override
    public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem) {
        if (!plugin.inHunterArea())
            return;

        switch (itemId)
        {
            case ItemID.CHISEL:
            case /*ItemID.JEWELLERS_CHISEL*/34024:
                if (!config.inventoryChiselEnabled())
                    return;

                renderBox(graphics, widgetItem, config.inventoryChiselColour());

                break;
            case ItemID.HUNTING_ANTELOPEMOON_HORN:
                if (!config.inventoryHornEnabled())
                    return;

                renderBox(graphics, widgetItem, config.inventoryHornColour());

                break;
        }
    }

    public void renderBox(Graphics2D graphics, WidgetItem widgetItem, Color color)
    {
        var bounds = widgetItem.getCanvasBounds();
        if (bounds == null || bounds.width <= 0 || bounds.height <= 0)
            return;
        var mousePosition = client.getMouseCanvasPosition();

        var borderColour = new Color(color.getRed(), color.getGreen(), color.getBlue(), 255);
        OverlayUtil.renderHoverableArea(graphics, bounds, mousePosition, color, borderColour, borderColour.darker());
    }
}

package org.zhbot.moonlight_antelope_hunting;

import net.runelite.api.*;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.*;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.ObjectID;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.components.ProgressPieComponent;

import javax.inject.Inject;
import java.awt.*;
import java.util.Map;
import java.util.Set;

public class MoonlightAntelopeHuntingOverlay extends Overlay {
    private static final Map<Integer, Integer> PITFALL_VARBIT_MAP = Map.of(
            ObjectID.HUNTING_PITFALL_22, VarbitID.HUNT_PITFALL_STATE22,
            ObjectID.HUNTING_PITFALL_23, VarbitID.HUNT_PITFALL_STATE23,
            ObjectID.HUNTING_PITFALL_24, VarbitID.HUNT_PITFALL_STATE24,
            ObjectID.HUNTING_PITFALL_25, VarbitID.HUNT_PITFALL_STATE25
    );

    private static final Set<WorldPoint> INVALID_TILES = Set.of(
            new WorldPoint(1555, 9421, 0),
            new WorldPoint(1556, 9421, 0),

            new WorldPoint(1555, 9418, 0),
            new WorldPoint(1556, 9418, 0),

            new WorldPoint(1559, 9416, 0),
            new WorldPoint(1559, 9415, 0),

            new WorldPoint(1562, 9416, 0),
            new WorldPoint(1562, 9415, 0),

            new WorldPoint(1564, 9416, 0),
            new WorldPoint(1565, 9416, 0),
            new WorldPoint(1564, 9415, 0),
            new WorldPoint(1565, 9415, 0),

            new WorldPoint(1564, 9419, 0),
            new WorldPoint(1565, 9419, 0),

            new WorldPoint(1565, 9425, 0),
            new WorldPoint(1565, 9424, 0),

            new WorldPoint(1562, 9425, 0),
            new WorldPoint(1562, 9424, 0)
    );

    private final Client client;
    private final MoonlightAntelopeHuntingPlugin plugin;
    private final MoonlightAntelopeHuntingConfig config;

    @Inject
    private MoonlightAntelopeHuntingOverlay(Client client, MoonlightAntelopeHuntingPlugin plugin, MoonlightAntelopeHuntingConfig config)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!plugin.inHunterArea())
            return null;

        var inventory = client.getItemContainer(InventoryID.INV);
        if (inventory == null)
            return null;

        var logCount = plugin.getLogCounts().getOrDefault(ItemID.LOGS, 0);

        if (config.rootsEnabled())
        {
            Color logColour;
            if (logCount == 0)
                logColour = config.rootsEmptyColour();
            else if (logCount < 3)
                logColour = config.rootsLowColour();
            else
                logColour = config.rootsFullColour();

            for (var root : plugin.getRootGameObjects())
            {
                renderObject(graphics, root, logColour);
                renderText(graphics, root, logCount + "/3", logColour);
            }
        }

        logCount = 0;
        for (var count : plugin.getLogCounts().values())
            logCount += count;

        if (config.pitfallEnabled())
        {
            var pitColour = logCount > 0 ? config.pitfallDefaultColour() : config.pitfallEmptyColour();

            for (var pit : plugin.getPitGameObjects())
            {
                var colour = pitColour;
                var varbitId = PITFALL_VARBIT_MAP.get(pit.getId());
                if (varbitId != null)
                {
                    switch (client.getVarbitValue(varbitId))
                    {
                        case 1:
                        case 2:
                            colour = config.pitfallTrappedColour();
                            break;
                        case 3:
                        case 4:
                            colour = config.pitfallCaughtColour();
                            break;
                    }
                }
                renderObject(graphics, pit, colour);
            }
        }

        if (config.antelopesEnabled())
        {
            var localPlayer = client.getLocalPlayer();
            for (var npc : plugin.getActiveNPCs())
            {
                if (plugin.isCaught(npc))
                    continue;

                var colour = npc.getInteracting() == localPlayer ? config.antelopesTauntedColour() : config.antelopesColour();

                if (config.antelopesRenderMode().isShowHull())
                    renderNPC(graphics, npc, colour);

                if (config.antelopesRenderMode().isShowTile())
                    renderTile(graphics, npc, colour);

            }

            var currentTick = client.getTickCount();
            var iterator = plugin.getDeadNPCs().iterator();
            while (iterator.hasNext())
            {
                var npc = iterator.next();

                var ticksLeft = npc.getRespawnTick() - currentTick;
                if (ticksLeft <= 0)
                {
                    iterator.remove();
                    continue;
                }

                renderRespawn(graphics, npc.getLocation(), config.antelopesRespawnColour(), 2, (double)ticksLeft / MoonlightAntelopeHuntingPlugin.ANTELOPE_RESPAWN_TIME);
            }
        }

        if (config.invalidTilesEnabled())
            for (var tile : INVALID_TILES)
                renderFilledTile(graphics, tile, config.invalidTilesColour());

        return null;
    }

    private void renderObject(Graphics2D graphics, GameObject gameObject, Color color)
    {
        var area = gameObject.getClickbox();
        var mousePosition = client.getMouseCanvasPosition();

        var borderColour = new Color(color.getRed(), color.getGreen(), color.getBlue(), 255);
        OverlayUtil.renderHoverableArea(graphics, area, mousePosition, color, borderColour, borderColour.darker());
    }

    private void renderText(Graphics2D graphics, GameObject gameObject, String text, Color color)
    {
        renderText(graphics, gameObject.getLocalLocation(), text, color);
    }

    private void renderText(Graphics2D graphics, WorldPoint worldPoint, String text, Color color)
    {
        renderText(graphics, LocalPoint.fromWorld(client, worldPoint), text, color);
    }

    private void renderText(Graphics2D graphics, LocalPoint localPoint, String text, Color color)
    {
        var point = Perspective.getCanvasTextLocation(client, graphics, localPoint, text, 0);
        if (point == null)
            return;

        OverlayUtil.renderTextLocation(graphics, point, text, color);
    }

    private void renderNPC(Graphics2D graphics, NPC npc, Color color)
    {
        var hull = npc.getConvexHull();
        var mousePosition = client.getMouseCanvasPosition();

        var borderColour = new Color(color.getRed(), color.getGreen(), color.getBlue(), 255);
        OverlayUtil.renderHoverableArea(graphics, hull, mousePosition, color, borderColour, borderColour.darker());
    }

    private void renderRespawn(Graphics2D graphics, WorldPoint worldPoint, Color color, int size, double progress)
    {
        var localPoint = LocalPoint.fromWorld(client, worldPoint);
        if (localPoint == null)
            return;

        int offset = (size - 1) * Perspective.LOCAL_HALF_TILE_SIZE;
        var centeredLocalPoint = new LocalPoint(localPoint.getX() + offset, localPoint.getY() + offset, localPoint.getWorldView());

        var tilePoly = Perspective.getCanvasTileAreaPoly(client, centeredLocalPoint, size);
        if (tilePoly == null)
            return;

        OverlayUtil.renderPolygon(graphics, tilePoly, color);

        var pie = new ProgressPieComponent();
        pie.setPosition(Perspective.localToCanvas(client, centeredLocalPoint, worldPoint.getPlane()));
        pie.setProgress(progress);
        pie.setBorderColor(color.darker());
        pie.setFill(color);
        pie.render(graphics);
    }

    private void renderFilledTile(Graphics2D graphics, WorldPoint worldPoint, Color color)
    {
        var localPoint = LocalPoint.fromWorld(client, worldPoint);
        if (localPoint == null)
            return;

        var tilePoly = Perspective.getCanvasTilePoly(client, localPoint);
        if (tilePoly == null)
            return;

        graphics.setColor(color);
        graphics.fill(tilePoly);
    }

    private void renderTile(Graphics2D graphics, NPC npc, Color color)
    {
        var tilePoly = npc.getCanvasTilePoly();
        if (tilePoly == null)
            return;

        OverlayUtil.renderPolygon(graphics, tilePoly, color);
    }
}

package org.zhbot.moonlight_antelope_hunting;

import com.google.inject.Provides;
import javax.inject.Inject;

import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.*;
import net.runelite.api.gameval.*;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.ObjectID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

import java.util.*;

@Slf4j
@PluginDescriptor(
	name = "Moonlight Antelope Hunting"
)
public class MoonlightAntelopeHuntingPlugin extends Plugin
{
	private static final WorldPoint CENTER = new WorldPoint(1561, 9421, 0);
	private static final int DISTANCE = 10;

	public static final int ANTELOPE_RESPAWN_TIME = 45;

	private static final Set<Integer> LOG_IDS = Set.of(
			net.runelite.api.gameval.ItemID.LOGS,
			net.runelite.api.gameval.ItemID.OAK_LOGS,
			net.runelite.api.gameval.ItemID.WILLOW_LOGS,
			net.runelite.api.gameval.ItemID.MAPLE_LOGS,
			net.runelite.api.gameval.ItemID.YEW_LOGS,
			ItemID.MAGIC_LOGS
	);

	private static final int[] PITFALL_ANIM_IDS = {
			SpotanimID.HUNTING_PITFALL_COLLAPSE_0,
			SpotanimID.HUNTING_PITFALL_COLLAPSE_1,
			SpotanimID.HUNTING_PITFALL_COLLAPSE_2,
			SpotanimID.HUNTING_PITFALL_COLLAPSE_3
	};

	@Inject
	private Client client;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private MoonlightAntelopeHuntingConfig config;

	@Inject
	private MoonlightAntelopeHuntingOverlay overlay;

	@Inject
	private MoonlightAntelopeHuntingInventoryOverlay inventoryOverlay;

	@Getter
	private final List<GameObject> rootGameObjects = new ArrayList<>();

	@Getter
	private final List<GameObject> pitGameObjects = new ArrayList<>();

	@Getter
	private final List<NPC> activeNPCs = new ArrayList<>();

	@Getter
	private final List<DeadNPC> deadNPCs = new ArrayList<>();

	private final Set<Integer> fallingNPCs = new HashSet<>();
	private final Map<Integer, Map<WorldPoint, Integer>> spawnFrequencies = new HashMap<>();

	@Getter
	private final Map<Integer, Integer> logCounts = new HashMap<>();

	@Override
	protected void startUp() throws Exception
	{
		overlayManager.add(overlay);
		overlayManager.add(inventoryOverlay);
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(overlay);
		overlayManager.remove(inventoryOverlay);

		rootGameObjects.clear();
		pitGameObjects.clear();

		activeNPCs.clear();
		deadNPCs.clear();
		spawnFrequencies.clear();

		logCounts.clear();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState gameState = event.getGameState();
		if (gameState == GameState.LOADING)
		{
			rootGameObjects.clear();
			pitGameObjects.clear();

			activeNPCs.clear();
			deadNPCs.clear();
		}
	}

	@Subscribe
	private void onGameObjectSpawned(GameObjectSpawned event)
	{
		var gameObject = event.getGameObject();
		if (!inHunterArea(gameObject.getWorldLocation()))
			return;

		switch (gameObject.getId())
		{
			case ObjectID.HG_CAVEKIT_ROOTS01_BOTTOM01:
				rootGameObjects.add(gameObject);
				break;
			case ObjectID.HUNTING_PITFALL_22:
			case ObjectID.HUNTING_PITFALL_23:
			case ObjectID.HUNTING_PITFALL_24:
			case ObjectID.HUNTING_PITFALL_25:
				pitGameObjects.add(gameObject);
				break;
		}
	}

	@Subscribe
	private void onGameObjectDespawned(GameObjectDespawned event)
	{
		var gameObject = event.getGameObject();

		switch (gameObject.getId())
		{
			case ObjectID.HG_CAVEKIT_ROOTS01_BOTTOM01:
				rootGameObjects.remove(gameObject);
				break;
			case ObjectID.HUNTING_PITFALL_22:
			case ObjectID.HUNTING_PITFALL_23:
			case ObjectID.HUNTING_PITFALL_24:
			case ObjectID.HUNTING_PITFALL_25:
				pitGameObjects.remove(gameObject);
				break;
		}
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event) {
		NPC npc = event.getNpc();
		if (npc.getId() != NpcID.MOONLIGHT_ANTELOPE)
			return;

		activeNPCs.add(npc);
		var index = npc.getIndex();

        var counts = spawnFrequencies.computeIfAbsent(index, k -> new HashMap<>());
		counts.merge(npc.getWorldLocation(), 1, Integer::sum);

		deadNPCs.removeIf(deadNPC -> deadNPC.getIndex() == index);
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		if (!(event.getActor() instanceof NPC))
			return;

		NPC npc = (NPC) event.getActor();
		if (npc.getId() != NpcID.MOONLIGHT_ANTELOPE)
			return;

		if (npc.getAnimation() != AnimationID.UNICORN_REWORK_PITFALL_DEATH)
			return;

		fallingNPCs.add(npc.getIndex());
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event) {
		NPC npc = event.getNpc();
		if (npc.getId() != NpcID.MOONLIGHT_ANTELOPE)
			return;

		activeNPCs.remove(npc);

		var index = npc.getIndex();
		if (!fallingNPCs.contains(index))
			return;
		fallingNPCs.remove(index);

		var spawnTile = getMostCommonSpawnTile(index);
		if (spawnTile == null)
			return;

		deadNPCs.add(new DeadNPC(index, spawnTile, client.getTickCount() + ANTELOPE_RESPAWN_TIME));
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.INV)
			return;

		var inventory = event.getItemContainer();

		for (var logId : LOG_IDS)
			logCounts.put(logId, inventory.count(logId));
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (!config.antelopesRemoveTease())
			return;

		var option = Text.removeTags(event.getOption());
		if (!option.equals("Tease"))
			return;

		var entry = event.getMenuEntry();
		var npc = entry.getNpc();
		if (npc == null || npc.getId() != NpcID.MOONLIGHT_ANTELOPE)
			return;

		if (isCaught(npc))
			client.getMenu().removeMenuEntry(entry);

	}

	@Provides
	MoonlightAntelopeHuntingConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(MoonlightAntelopeHuntingConfig.class);
	}

	public boolean inHunterArea()
	{
		var localPlayer = client.getLocalPlayer();
		if (localPlayer == null)
			return false;

		return inHunterArea(localPlayer.getWorldLocation());
	}

	public boolean inHunterArea(WorldPoint point)
	{
		return point.distanceTo(CENTER) <= DISTANCE;
	}

	private WorldPoint getMostCommonSpawnTile(int index)
	{
		var counts = spawnFrequencies.get(index);
		if (counts == null || counts.isEmpty())
			return null;

		WorldPoint mostCommon = null;
		var highestCount = 0;

		for (var entry : counts.entrySet())
		{
			if (entry.getValue() > highestCount)
			{
				highestCount = entry.getValue();
				mostCommon = entry.getKey();
			}
		}

		if (highestCount <= 1)
			return null;

		return mostCommon;
	}

	public boolean isCaught(NPC npc)
	{
		for (int id : PITFALL_ANIM_IDS)
			if (npc.hasSpotAnim(id))
				return true;

		var interacting = npc.getInteracting();
		if (interacting != null && interacting != client.getLocalPlayer())
			return true;

		var npcArea = npc.getWorldArea();
		if (npcArea != null)
		{
			for (var pit : pitGameObjects)
			{
				var pitLocation = pit.getWorldLocation();
				var pitArea = new WorldArea(pitLocation.getX(), pitLocation.getY(), pit.sizeX(), pit.sizeY(), pitLocation.getPlane());

				if (npcArea.intersectsWith(pitArea))
					return true;
			}
		}

		return false;
	}
}

